package cn.iocoder.yudao.module.platform.api.tenant;import cn.iocoder.yudao.module.platform.api.tenant.dto.menu.TenantMenuListReqDTO;import cn.iocoder.yudao.module.platform.api.tenant.dto.menu.TenantMenuRespDTO;import cn.iocoder.yudao.module.platform.controller.center.tenant.vo.menu.TenantMenuListReqVO;import cn.iocoder.yudao.module.platform.convert.tenant.TenantMenuConvert;import cn.iocoder.yudao.module.platform.service.tenant.PlatformTenantMenuService;import org.springframework.stereotype.Service;import javax.annotation.Resource;import java.util.Collection;import java.util.List;/** * @author zhusy * @since 2022/8/6 */@Servicepublic class TenantMenuApiImpl implements TenantMenuApi {    @Resource    private PlatformTenantMenuService platformTenantMenuService;    @Override    public List<TenantMenuRespDTO> getTenantMenuList(TenantMenuListReqDTO reqDTO) {        TenantMenuListReqVO reqVO = TenantMenuConvert.INSTANCE.convert1(reqDTO);        return TenantMenuConvert.INSTANCE.convert1(platformTenantMenuService.getMenus(reqVO));    }    @Override    public List<TenantMenuRespDTO> getMenuListFromCache(Collection<Long> menuIds, Collection<Integer> menuTypes, Collection<Integer> menusStatuses) {        return TenantMenuConvert.INSTANCE.convert1(platformTenantMenuService.getMenuListFromCache(menuIds, menuTypes, menusStatuses));    }    @Override    public List<TenantMenuRespDTO> getMenuListByPermissionFromCache(String permission) {        return TenantMenuConvert.INSTANCE.convert1(platformTenantMenuService.getMenuListByPermissionFromCache(permission));    }}